                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))
    return comps


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The long straight stroke acts as a pointer; recolor the nearest
    # foreground component lying on its continuation.
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    comps = _components(grid, bg)
    strokes = []
    for color, cells in comps:
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        if len(set(cols)) == 1 and len(cells) >= 5:
            strokes.append((len(cells), color, 'v', cols[0], min(rows), max(rows)))
        if len(set(rows)) == 1 and len(cells) >= 5:
            strokes.append((len(cells), color, 'h', rows[0], min(cols), max(cols)))
    if not strokes:
        return out
    _, color, direction, axis, lo, hi = max(strokes)
    candidates = []
    for other_color, cells in comps:
        if other_color == color:
            continue
        if direction == 'v':
            # Prefer the nearest object beyond the upper end of the stroke.
            overlap = [r for r, c in cells if c == axis and r < lo]
            if overlap:
                candidates.append((lo - max(overlap), cells))
        else:
            overlap = [c for r, c in cells if c == axis and c < lo]
            if overlap:
                candidates.append((lo - max(overlap), cells))
    if candidates:
        _, target = min(candidates, key=lambda item: item[0])
        for r, c in target:
            out[r][c] = color
    return out


